/**
 * 负责普通夜能力唯一库存的数据复制、查询、原生安装和通用 metadata 提交。
 * 输入为原角色、捕获实例、已准备 payload 与明确日期；输出保留原字典／实例引用和能力变化事实。
 * 本 owner 写 abilities、retiredAbilityIds 及通用启停／次数／到期字段；原生 payload 准备仍归 ability_changes，
 * 授予／转移的来源与状态政策仍归 night-ability-grants，具体瓶数、梦历史、借用抑制及 Demon 审计另有原权威。
 * 字典创建、退休 ID 修订和逐字段提交保原求值顺序；发表或后续写入失败不回滚已完成前缀。
 * 数据复制不新增严格 live schema、JSON 档案接受或行动许可；readonly 视图仍是同一对象，不是冻结或第二库存。
 */

import type {
  PairSeerState,
  NightAbilityStates,
  RoleInspectionPolicy,
  NightAbilityKind,
  AbilitySource,
  NightAbilityReadStates,
  NightAbilityReadState,
} from "@ai-werewolf-arena/game-contract";
import { readPairSeerState } from "./fragrant_pair_seer/state";
import { nativePotionSecondTurn } from "./witch/policies";
import { Role } from "../../../core/domain/model";
import type { RoleComponent } from "../../../core/domain/components/role";
import type { RoleInitializationComponent } from "./contracts";
import { COMPONENT } from "../../../core/domain/components/names";
import type { EntityId, GameEvent } from "../../../core/domain/model";
import type { World } from "../../../core/domain/world";
import { roleOf, emit } from "./night-ability-change-runtime";
import { types as utilTypes } from "node:util";
import type {
  NightAbilityMetadata,
  AbilityStatus,
} from "@ai-werewolf-arena/game-contract/night-ability-views";
export { projectRoleInspectionState, projectSeerState, projectWitchState } from "./player_state";


export const ROLE_INSPECTION_POLICY_ROLES: Readonly<Record<RoleInspectionPolicy, Role>> = {
  gargoyle: Role.Gargoyle,
  psychic: Role.Psychic,
  mirror: Role.MirrorGirl,
  pure_white: Role.PureWhiteGirl,
  wolf_witch: Role.WolfWitch,
};


/** Pair 初始化和玩家投影共享此原纯数据校验；不读实例、World 或授予能力权限。 */
export function projectPairState(value: unknown): PairSeerState {
  const state = readPairSeerState(value);
  if (!state) throw Error("fragrant_pair_state_invalid");
  return state;
}
type NightAbilityUnion = {
  [P in NightAbilityKind]: NightAbilityMetadata & {
    kind: P;
    state: NightAbilityStates[P];
  };
}[NightAbilityKind];
export type NightAbility<K extends NightAbilityKind = NightAbilityKind> = Extract<
  NightAbilityUnion,
  { kind: K }
>;
type NightAbilityReadUnion = {
  [K in NightAbilityKind]: Readonly<
    Omit<NightAbility<K>, "state" | "source" | "nightSuppression">
  > & {
    readonly state: NightAbilityReadStates[K];
    readonly source: Readonly<AbilitySource>;
    readonly nightSuppression?: Readonly<
      import("@ai-werewolf-arena/game-contract").EclipseSuppression
    >;
  };
}[NightAbilityKind];
export type NightAbilityReadView<K extends NightAbilityKind = NightAbilityKind> = Extract<
  NightAbilityReadUnion,
  { kind: K }
>;

/** 复制有效 JSON 数据；可选 undefined 字段在落盘形状中保持缺失，不改 live 实例。 */
export function copyAbilityData<T>(value: T): T {
  const result = structuredClone(value),
    ancestors = new WeakSet<object>();
  const visit = (item: unknown): void => {
    if (item === null || typeof item === "string" || typeof item === "boolean") return;
    if (typeof item === "number" && Number.isFinite(item)) return;
    if (typeof item !== "object" || !item || ancestors.has(item))
      throw new Error("ability_state_not_json");
    ancestors.add(item);
    if (Array.isArray(item)) {
      for (let index = 0; index < item.length; index++) {
        if (!Object.hasOwn(item, index)) throw new Error("ability_state_not_json");
        visit(item[index]);
      }
    } else {
      const prototype = Object.getPrototypeOf(item);
      if (prototype !== Object.prototype && prototype !== null)
        throw new Error("ability_state_not_json");
      for (const [key, entry] of Object.entries(item)) {
        if (entry === undefined) delete (item as Record<string, unknown>)[key];
        else visit(entry);
      }
    }
    ancestors.delete(item);
  };
  visit(result);
  return result;
}

/** 资源只归该玩家实际库存中的实例，不另建并行角色状态。 */
export function allNightAbilities(role: RoleComponent | undefined): NightAbilityReadView[] {
  const stored = (role as { readonly privateState: { readonly abilities?: unknown } } | undefined)
    ?.privateState.abilities as Readonly<Record<string, NightAbilityReadView>> | undefined;
  return stored
    ? Object.values(stored).sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))
    : [];
}

/** 检查原 nightSuppression 描述符，畸形或访问器保持 blocked，不调用该字段 getter；只读结果不授予权限／lease。 */
export function nightAbilityDisabled(ability: NightAbilityReadView): boolean {
  const blocker = Object.getOwnPropertyDescriptor(ability, "nightSuppression");
  return ability.disabled || (!!blocker && (!("value" in blocker) || blocker.value !== undefined));
}

export function abilityStatus(ability: NightAbilityReadView, day: number): AbilityStatus {
  if (nightAbilityDisabled(ability) || ability.deathExpired) return "disabled";
  if (day < ability.startsOnDay) return "pending";
  if (ability.expiresAfterDay !== undefined && day > ability.expiresAfterDay) return "expired";
  if (ability.maxUses !== null && ability.uses >= ability.maxUses) return "spent";
  if (
    ability.lastUsedDay === day &&
    !(ability.kind === "potion" && nativePotionSecondTurn(ability, day))
  )
    return "used_this_night";
  if (
    ability.kind === "potion" &&
    ability.source.kind === "native" &&
    ability.source.role === Role.Witch &&
    ability.state.potionPolicy === "awa_both_native_experimental_v1" &&
    ability.state.potionTurnClosedDay === day
  )
    return "used_this_night";
  return "active";
}

export function findNightAbility<K extends NightAbilityKind>(
  role: RoleComponent | undefined,
  kind: K,
  id?: string,
): NightAbilityReadView<K> | undefined {
  const candidates = allNightAbilities(role).filter(
    (ability): ability is NightAbilityReadView<K> => ability.kind === kind,
  );
  if (id !== undefined) return candidates.find((ability) => ability.id === id);
  // 原调用者优先选原生实例；仅有一份明确受赠实例时才采用该实例。
  return (
    candidates.find((ability) => ability.source.kind === "native") ??
    (candidates.length === 1 ? candidates[0] : undefined)
  );
}

export function activeNightAbility<K extends NightAbilityKind>(
  role: RoleComponent | undefined,
  kind: K,
  day: number,
  id?: string,
): NightAbilityReadView<K> | undefined {
  const ability = findNightAbility(role, kind, id);
  return ability && abilityStatus(ability, day) === "active" ? ability : undefined;
}

/** 读取原退休 ID 列表，不授予库存写权限。 */
export function retiredNightAbilityIds(role: RoleComponent): readonly string[] {
  return ((role.privateState as { readonly retiredAbilityIds?: unknown }).retiredAbilityIds ??
    []) as readonly string[];
}

/**
 * 原准备方已按各族规则复制并接受 payload；这里先创建字典，再读退休 ID 修订原生编号。
 * kind／来源失配时保留旧实例；匹配只替换 state，原 metadata、次数和起效日期保持。
 * 字典已创建后退休列表读取失败，不撤销这一前缀；本步不新增状态 schema 或行动许可。
 */
export function commitPreparedNativeAbility<K extends NightAbilityKind>(
  role: RoleComponent,
  kind: K,
  ownedState: NightAbilityStates[K],
): NightAbilityReadState<K> {
  const stored = ((role.privateState as { abilities?: Record<string, NightAbility> }).abilities ??=
    {}) as Record<string, NightAbility>;
  const retired = ((role.privateState as { readonly retiredAbilityIds?: unknown })
    .retiredAbilityIds ?? []) as string[];
  const baseId = `native:${kind}`;
  let id = baseId,
    revision = 1;
  while (retired.includes(id)) id = `${baseId}:${++revision}`;
  const existing = stored[id];
  if (existing) {
    if (
      existing.kind !== kind ||
      existing.source.kind !== "native" ||
      existing.source.role !== role.role
    )
      throw new Error("ability_native_binding_conflict");
    existing.state = ownedState;
  } else {
    stored[id] = {
      id,
      kind,
      state: ownedState,
      source: { kind: "native", role: role.role },
      sourceDisclosed: true,
      startsOnDay: 1,
      maxUses: null,
      uses: 0,
      lastUsedDay: null,
      disabled: false,
    } as NightAbility;
  }
  return ownedState as NightAbilityReadState<K>;
}

/**
 * 按原库存 ID 寻找实例；死亡到期不能重开，启停值已一致时不发布事实。
 * 先写 disabled 再发表，事件写入失败仍保留已完成的启停值，不退还具体资源。
 */
export function setNightAbilityEnabled(
  world: World,
  actorId: EntityId,
  id: string,
  enabled: boolean,
  events: GameEvent[],
): void {
  const ability = allNightAbilities(roleOf(world, actorId)).find((ability) => ability.id === id);
  if (!ability) throw new Error("ability_instance_missing");
  if (enabled && ability.deathExpired) throw new Error("ability_lucky_expired_on_death");
  if (ability.disabled === !enabled) return;
  (ability as { disabled: boolean }).disabled = !enabled;
  emit(events, actorId, ability, enabled ? "enabled" : "disabled");
}

/**
 * 退役角色已核对原体／捕获槽的借用实例，只重定义原 disabled 数据属性。
 * 目标 supplier 在 Object.defineProperty 方法查找之后执行，保原 late 字段读取位置。
 * 不按可变 id 重查、不读或执行替换的 disabled getter/setter、不删槽／退休 ID，不发布启停事实。
 * 借用租约、原主抑制和已付 payload 仍归具体 Frame；本写入不提供新行动权限或退款。
 */
export function retireBorrowedNightAbility(readBorrowed: () => NightAbilityReadView): void {
  Object.defineProperty(readBorrowed(), "disabled", {
    value: true,
    writable: true,
    enumerable: true,
    configurable: true,
  });
}

/** 实际死亡到期跟随同一实例经过转移／复活；已经付款的夜效果仍按原政策保留。 */
export function expireLuckyAbilitiesOnDeath(
  world: World,
  actorId: EntityId,
  events: GameEvent[],
): void {
  for (const ability of allNightAbilities(world.getComponent(actorId, COMPONENT.Role))) {
    if (
      (ability.activation !== "lucky" && ability.activation !== "black_market") ||
      ability.deathExpired
    )
      continue;
    (ability as { deathExpired?: boolean }).deathExpired = true;
    (ability as { disabled: boolean }).disabled = true;
    emit(events, actorId, ability, "disabled");
  }
}


/** 初始化／学习流程仍在原调用点决定起效日；这里只写原 startsOnDay，不推进业务时钟。 */
export function setNightAbilityStartDay(ability: NightAbilityReadView, day: number): void {
  (ability as { startsOnDay: number }).startsOnDay = day;
}

/** 原 status 重检后先记 lastUsedDay，再可选增加 uses；payload 库存与已付效果继续归具体机制。 */
export function recordNightAbilityUse(
  ability: NightAbilityReadView,
  day: number,
  consumed: boolean,
): void {
  if (abilityStatus(ability, day) !== "active") throw new Error("ability_not_active");
  (ability as { lastUsedDay: number | null }).lastUsedDay = day;
  if (consumed) (ability as { uses: number }).uses++;
}

/** 本族初始化已经先完成；这里只在原清空点安装新空字典，不读取退休列表或补偿旧库存。 */
export function initializeNightAbilityInventory(role: RoleInitializationComponent): void {
  role.privateState.abilities = {};
}

/** 来源与安装政策已由授予 owner 复验；安装先于发表，同一事件失败不撤回已安装实例。 */
export function commitGrantedNightAbility(
  role: RoleComponent,
  actorId: EntityId,
  ability: NightAbility,
  events: GameEvent[],
): NightAbility {
  // 原字典赋值已发生后才发布；push／时钟／来源克隆失败都保留已安装实例。
  const stored = ((role.privateState as { abilities?: Record<string, NightAbility> }).abilities ??=
    {}) as Record<string, NightAbility>;
  stored[ability.id] = ability;
  emit(events, actorId, ability, "granted");
  return ability;
}

/** 转移只接收稳定的自有数据槽；这不是其他 live payload 的通用 schema，也不改变授予的接受面。 */
function transferPrivateState(role: RoleComponent): object {
  if (utilTypes.isProxy(role)) throw new Error("ability_transfer_inventory_invalid");
  const descriptor = Object.getOwnPropertyDescriptor(role, "privateState");
  const value = descriptor && "value" in descriptor ? descriptor.value : undefined;
  if (!value || typeof value !== "object" || utilTypes.isProxy(value))
    throw new Error("ability_transfer_inventory_invalid");
  const prototype = Object.getPrototypeOf(value);
  if (prototype !== Object.prototype && prototype !== null)
    throw new Error("ability_transfer_inventory_invalid");
  return value;
}

/** 库存与条目保持同引用；不调用库存访问器，也不把两次 getter 相等当作稳定性证明。 */
function transferInventory(privateState: object): Record<string, NightAbility> | undefined {
  const descriptor = Object.getOwnPropertyDescriptor(privateState, "abilities");
  if (!descriptor) {
    if ("abilities" in privateState) throw new Error("ability_transfer_inventory_invalid");
    return undefined;
  }
  if (!("value" in descriptor)) throw new Error("ability_transfer_inventory_invalid");
  const value = descriptor.value;
  if (value === undefined || value === null) return undefined;
  if (typeof value !== "object" || utilTypes.isProxy(value))
    throw new Error("ability_transfer_inventory_invalid");
  const prototype = Object.getPrototypeOf(value);
  if (prototype !== Object.prototype && prototype !== null)
    throw new Error("ability_transfer_inventory_invalid");
  for (const key of Reflect.ownKeys(value)) {
    if (!("value" in Object.getOwnPropertyDescriptor(value, key)!))
      throw new Error("ability_transfer_inventory_invalid");
  }
  return value as Record<string, NightAbility>;
}

/**
 * 完整预检已完成后，唯一库存 owner 晚核原角色与真实数据槽，再按源删除／退休、目标安装、两条事实提交。
 * 同角色、同容器、同字典或源条目别名不属于合法转移输入；空目标字典仍到安装点才创建。
 * 退休列表的 getter／push 在源删除后原点执行；任何抛错保已完成前缀与原 Error，不退款、不补偿、不暗改 disabled。
 * 记录 sink 只获得事件输入，不取得库存写权；任意强制写回旧槽的 JS monkeypatch 不属于这一有界唯一 owner 保证。
 */
export function commitTransferredNightAbility(
  world: World,
  source: RoleComponent,
  originalPrivateState: object,
  target: RoleComponent,
  fromId: EntityId,
  toId: EntityId,
  id: string,
  ability: NightAbilityReadView,
  received: NightAbility,
  events: GameEvent[],
): void {
  if (source === target) throw new Error("ability_transfer_inventory_alias");
  if (roleOf(world, fromId) !== source || roleOf(world, toId) !== target)
    throw new Error("ability_transfer_owner_revoked");
  const sourcePrivate = transferPrivateState(source), targetPrivate = transferPrivateState(target);
  if (sourcePrivate !== originalPrivateState) throw new Error("ability_transfer_owner_revoked");
  if (sourcePrivate === targetPrivate) throw new Error("ability_transfer_inventory_alias");
  const sourceStored = transferInventory(sourcePrivate), targetStored = transferInventory(targetPrivate);
  if (sourceStored === targetStored && sourceStored !== undefined)
    throw new Error("ability_transfer_inventory_alias");
  if (utilTypes.isProxy(ability)) throw new Error("ability_transfer_inventory_invalid");
  const sourceEntry = sourceStored && Object.getOwnPropertyDescriptor(sourceStored, id),
    sourceId = Object.getOwnPropertyDescriptor(ability, "id");
  if (
    !sourceStored || !sourceEntry || !("value" in sourceEntry) || sourceEntry.value !== ability ||
    !sourceId || !("value" in sourceId) || sourceId.value !== id ||
    Reflect.ownKeys(sourceStored).filter(
      (key) => Object.getOwnPropertyDescriptor(sourceStored, key)!.value === ability,
    ).length !== 1
  )
    throw new Error("ability_transfer_source_slot_invalid");
  if (targetStored && Reflect.ownKeys(targetStored).some(
    (key) => Object.getOwnPropertyDescriptor(targetStored, key)!.value === ability,
  ))
    throw new Error("ability_transfer_inventory_alias");
  // 删除按已核对的真实 key，而非凭 Object.values 中的实例 id 猜测槽；失败不进入目标安装。
  delete sourceStored[id];
  (
    ((sourcePrivate as { retiredAbilityIds?: string[] }).retiredAbilityIds ??= []) as string[]
  ).push(id);
  // 空目标库存的创建也在源退休之后；安装或 granted 发布失败不会重装源槽。
  const stored = targetStored ?? ((targetPrivate as { abilities?: Record<string, NightAbility> }).abilities = {});
  stored[received.id] = received;
  emit(events, toId, received, "granted");
  emit(events, fromId, ability, "transferred_out");
}

/**
 * 负责普通夜能力授予、复制与明确转移的完整提交。输入为原 World、拥有者、安装数据与具体 statePolicy；
 * 输出为同一实际库存中的只读实例及原能力变化事实。校验、复制、来源复验和目标安装都由本模块负责。
 * 授予仍安装后发布；独立 F03 转移政策先完整预检，再由唯一库存 owner 先删源／退休、后安装目标／发布。
 * 转移拒绝共享或不稳定库存路径；异常保留已经发生的前缀和原 Error，不退款，记录 sink 不取得库存写权。
 * 字典安装／发布与删除／退休提交交唯一 abilities owner；本模块保完整来源政策，角色 payload、生命／租约和临时抑制仍有原负责人。
 * 数据复制仍消费唯一 copyAbilityData，原接受集合不加强；这不是全部角色状态 schema 或严格复盘 codec。
 */
import { roleInspectionPolicy } from "@ai-werewolf-arena/game-contract/role-inspection-policy";
import type { AbilitySource, NightAbilityKind, NightAbilityStates } from "@ai-werewolf-arena/game-contract";
import { isDeepStrictEqual } from "node:util";
import { DREAM_PROTECTION_POLICIES } from "../../../core/domain/board";
import { COMPONENT } from "../../../core/domain/components/names";
import { type EntityId, type GameEvent } from "../../../core/domain/model";
import type { World } from "../../../core/domain/world";
import type { RoleComponent } from "../../../core/domain/components/role";
import { captureNightLife, livingNightLife } from "../../../core/domain/night_effects";
import { allNightAbilities, copyAbilityData, commitGrantedNightAbility, commitTransferredNightAbility, type NightAbility, type NightAbilityReadView } from "./abilities";
import { projectNightState } from "../../observation/night-ability-projection";
import { roleOf } from "./night-ability-change-runtime";

/** 安装数据只声明赠予／复制来源；日期和资源政策仍在原安装流程核对，不代表已有行动许可。 */
export interface AbilityGrant<K extends NightAbilityKind> {
  id: string;
  kind: K;
  state: NightAbilityStates[K];
  source: Extract<AbilitySource, { kind: "gift" | "copy" }>;
  startsOnDay: number;
  expiresAfterDay?: number;
  maxUses: number | null;
  sourceDisclosed?: boolean;
  activation?: "lucky" | "black_market";
}

/** 规则调用者明确提供状态／资源政策，不隐式复制目标历史或重置已付库存。 */
export function grantNightAbility<K extends NightAbilityKind>(
  world: World,
  actorId: EntityId,
  input: AbilityGrant<K>,
  events: GameEvent[],
): NightAbilityReadView<K> {
  if (input.kind === "pair_check") throw Error("ability_pair_native_only");
  if (input.source.kind !== "gift" && input.source.kind !== "copy")
    throw new Error("ability_grant_source_invalid");
  const ability = copyAbilityData({
    ...input,
    sourceDisclosed: input.sourceDisclosed ?? false,
    uses: 0,
    lastUsedDay: null,
    disabled: false,
  }) as unknown as NightAbility<K>;
  const role = validateAbilityInstall(world, actorId, ability);
  return commitGrantedNightAbility(role, actorId, ability, events) as NightAbilityReadView<K>;
}

/** 完整原安装预检只返回实际目标 Role；库存提交另有唯一 owner，授予和转移共用原政策。 */
function validateAbilityInstall(
  world: World,
  actorId: EntityId,
  ability: NightAbility,
): RoleComponent {
  const input = ability;
  if (input.kind === "pair_check") throw Error("ability_pair_native_only");
  if (input.kind === "role_check") roleInspectionPolicy(input.state);
  if (
    input.kind === "dream" &&
    input.state.protectionPolicy !== undefined &&
    !DREAM_PROTECTION_POLICIES.includes(input.state.protectionPolicy)
  )
    throw new Error("ability_dream_policy_invalid");
  const source = input.source;
  if (
    input.kind === "role_check" &&
    roleInspectionPolicy(input.state) === "mirror" &&
    source.kind !== "transfer" &&
    (Object.keys(input.state)
      .filter((key) => key !== "inspectionPolicy")
      .sort()
      .join() !== "history,lastDay,lastTarget,policy" ||
      input.state.lastTarget !== null ||
      input.state.lastDay !== null ||
      !Array.isArray(input.state.history) ||
      input.state.history.length !== 0 ||
      Object.keys(input.state.history).length !== 0 ||
      input.uses !== 0 ||
      input.lastUsedDay !== null ||
      input.disabled)
  )
    throw new Error("ability_mirror_initial_state_invalid");
  if (source.kind === "native") throw new Error("ability_grant_source_invalid");
  const role = roleOf(world, actorId);
  if (
    !/^[a-z][a-z0-9:_-]{0,127}$/.test(input.id) ||
    input.id.startsWith("native:") ||
    !Number.isSafeInteger(input.startsOnDay) ||
    input.startsOnDay < 1 ||
    (input.expiresAfterDay !== undefined &&
      (!Number.isSafeInteger(input.expiresAfterDay) ||
        input.expiresAfterDay < input.startsOnDay)) ||
    (input.maxUses !== null && (!Number.isSafeInteger(input.maxUses) || input.maxUses < 0))
  )
    throw new Error("ability_grant_invalid");
  roleOf(world, source.actorId);
  if (
    input.activation === "black_market" &&
    (source.kind === "copy" ||
      input.sourceDisclosed !== false ||
      input.id !== "gift:black-market" ||
      role.camp !== "good" ||
      input.startsOnDay < 2)
  )
    throw new Error("ability_black_market_policy_invalid");
  const origin =
    source.kind === "copy"
      ? allNightAbilities(roleOf(world, source.actorId)).find(
          (ability) => ability.id === source.abilityId,
        )
      : undefined;
  if (origin?.activation === "lucky" || origin?.activation === "black_market")
    throw new Error("ability_copy_lucky_not_supported");
  if (
    input.activation !== undefined &&
    (!["lucky", "black_market"].includes(input.activation) ||
      !(
        input.activation === "black_market"
          ? ["seer_check", "potion"]
          : ["seer_check", "potion", "guard"]
      ).includes(input.kind) ||
      input.maxUses !== 1)
  )
    throw new Error("ability_lucky_policy_invalid");
  if (
    allNightAbilities(role).some((ability) => ability.id === input.id) ||
    (
      ((role.privateState as { readonly retiredAbilityIds?: unknown }).retiredAbilityIds ??
        []) as string[]
    ).includes(input.id)
  )
    throw new Error("ability_id_duplicate");
  if (
    source.kind !== "gift" &&
    !allNightAbilities(roleOf(world, source.actorId)).some(
      (ability) => ability.id === source.abilityId && ability.kind === input.kind,
    )
  )
    throw new Error("ability_source_mismatch");
  return role;
}

/** 先完成原复制／资源／来源／目标预检；转移提交保计数和原夜时点，但失败不再留下两份合法有效库存。 */
export function transferNightAbility<K extends NightAbilityKind>(
  world: World,
  fromId: EntityId,
  toId: EntityId,
  id: string,
  targetId: string,
  events: GameEvent[],
  options: {
    kind: K;
    statePolicy: (state: Readonly<NightAbilityStates[K]>) => NightAbilityStates[K];
    sourceDisclosed?: boolean;
  },
): void {
  if (fromId === toId) throw new Error("ability_transfer_same_owner");
  const source = roleOf(world, fromId),
    ability = allNightAbilities(source).find((ability) => ability.id === id);
  if (!ability) throw new Error("ability_instance_missing");
  if (ability.kind === "pair_check") throw Error("ability_pair_native_only");
  if (!options || options.kind !== ability.kind || typeof options.statePolicy !== "function")
    throw new Error("ability_transfer_policy_required");
  const black = ability.activation === "black_market",
    target = roleOf(world, toId),
    fromLife = captureNightLife(world, fromId),
    toLife = captureNightLife(world, toId),
    originalState = ability.state,
    originalSource = ability.source,
    sourcePrivate = source.privateState,
    targetPrivate = target.privateState,
    originalRole = source.role,
    targetRole = target.role;
  if (
    black &&
    (!fromLife ||
      !toLife ||
      source.camp !== "good" ||
      target.camp !== "good" ||
      targetId !== id ||
      options.sourceDisclosed === true)
  )
    throw new Error("ability_black_market_transfer_invalid");
  const before = black
    ? copyAbilityData({
        id: ability.id,
        kind: ability.kind,
        source: ability.source,
        startsOnDay: ability.startsOnDay,
        expiresAfterDay: ability.expiresAfterDay,
        maxUses: ability.maxUses,
        uses: ability.uses,
        lastUsedDay: ability.lastUsedDay,
        disabled: ability.disabled,
        deathExpired: ability.deathExpired,
        activation: ability.activation,
        sourceDisclosed: ability.sourceDisclosed,
        state: projectNightState(ability),
      })
    : undefined;
  // 政策回调消费独立数据；黑市随后复验原组件／生命／槽及规范化内容，不用复制结果恢复许可。
  const targetState = copyAbilityData(
    options.statePolicy(
      copyAbilityData(black ? projectNightState(ability) : ability.state) as NightAbilityStates[K],
    ),
  );
  if (
    black &&
    (options.kind !== ability.kind ||
      options.sourceDisclosed === true ||
      world.getComponent(fromId, COMPONENT.Role) !== source ||
      source.role !== originalRole ||
      source.camp !== "good" ||
      source.privateState !== sourcePrivate ||
      world.getComponent(toId, COMPONENT.Role) !== target ||
      target.role !== targetRole ||
      target.camp !== "good" ||
      target.privateState !== targetPrivate ||
      !livingNightLife(world, fromLife!) ||
      !livingNightLife(world, toLife!) ||
      allNightAbilities(source).find((candidate) => candidate.id === id) !== ability ||
      ability.state !== originalState ||
      ability.source !== originalSource ||
      !isDeepStrictEqual(
        before,
        copyAbilityData({
          id: ability.id,
          kind: ability.kind,
          source: ability.source,
          startsOnDay: ability.startsOnDay,
          expiresAfterDay: ability.expiresAfterDay,
          maxUses: ability.maxUses,
          uses: ability.uses,
          lastUsedDay: ability.lastUsedDay,
          disabled: ability.disabled,
          deathExpired: ability.deathExpired,
          activation: ability.activation,
          sourceDisclosed: ability.sourceDisclosed,
          state: projectNightState(ability),
        }),
      ))
  )
    throw new Error("ability_black_market_transfer_revoked");
  if (
    (ability.activation === "lucky" || ability.activation === "black_market") &&
    !isDeepStrictEqual(targetState, black ? projectNightState(ability) : ability.state)
  )
    throw new Error("ability_transfer_lucky_state_changed");
  // 转移保持资源；seer_check 明确政策可重置知识，role_check 保留完整历史，其他政策不能补库存。
  if (
    ability.kind === "guard" &&
    (targetState as NightAbilityStates["guard"]).lastTarget !== ability.state.lastTarget
  )
    throw new Error("ability_transfer_resources_changed");
  if (
    ability.kind === "dream" &&
    ((targetState as NightAbilityStates["dream"]).lastTarget !== ability.state.lastTarget ||
      (targetState as NightAbilityStates["dream"]).lastDay !== ability.state.lastDay ||
      (targetState as NightAbilityStates["dream"]).protectionPolicy !==
        ability.state.protectionPolicy)
  )
    throw new Error("ability_transfer_resources_changed");
  if (
    ability.kind === "potion" &&
    [
      "heal",
      "poison",
      "selfHealRule",
      "canSelfHeal",
      "healUsedThisNight",
      "poisonUsedThisNight",
    ].some(
      (key) =>
        (targetState as unknown as Record<string, unknown>)[key] !==
        (ability.state as unknown as Record<string, unknown>)[key],
    )
  )
    throw new Error("ability_transfer_resources_changed");
  if (ability.kind === "role_check" && !isDeepStrictEqual(targetState, ability.state))
    throw new Error("ability_transfer_role_inspection_history_changed");
  const received = copyAbilityData({
    ...ability,
    state: targetState,
    id: targetId,
    sourceDisclosed: options.sourceDisclosed ?? false,
    source: { kind: "transfer", actorId: fromId, abilityId: id },
  }) as NightAbility;
  const installationTarget = validateAbilityInstall(world, toId, received);
  // 预检和复制全通过才交库存写权；F03 的源先退休政策不伪装成旧失败前缀等价。
  commitTransferredNightAbility(world, source, sourcePrivate, installationTarget, fromId, toId, id, ability, received, events);
}

/**
 * 负责赠枪实例的授予、武装、转移、首次死亡收尾以及原体授权。
 * 输入为所属 World、原角色／生命／库存实例和明确业务夜时点；输出为同引用只读实例、
 * 捕获资格和原资源事实。owners/counters 是原唯一状态，不复制为第二份实例仓库。
 * 仅写 deathAbilities、retiredDeathAbilityIds 及本枪资源；不执行死亡、枪目标选择或录制 I/O。
 * 已付前缀和原 getter／提交顺序保持，替身或复活不能重新获得首次死亡枪权。
 */
import type { DeathGun, DeathGunReadView } from "@ai-werewolf-arena/game-contract";
import { COMPONENT } from "../../../core/domain/components/names";
import type { RoleComponent } from "../../../core/domain/components/role";
import { Camp, type EntityId, type GameEvent } from "../../../core/domain/model";
import { aliveLifeVersion, type AliveComponent } from "../../../core/domain/components/alive";
import type { World } from "../../../core/domain/world";
import { projectDeathGun } from "./player_state";

// 原体证明捕获原 World、角色、private 容器、生命版本及来源；相同字符串 ID 不构成授权。
interface GunOwner {
  world: World;
  actorId: number;
  role: RoleComponent;
  roleKind: RoleComponent["role"];
  camp: Camp;
  privateState: RoleComponent["privateState"];
  life: AliveComponent;
  version: number;
  id: string;
  source: DeathGunReadView["source"];
  sourceKind: DeathGun["source"]["kind"];
  sourceActor: number;
  sourceId?: string;
  grantedNight: number;
  armedOnNight: number | null;
}

// 两个原 WeakMap 随实际 owner 整体迁移；计数只在成功安装后推进，不查询 RNG 或时钟。
const owners = new WeakMap<DeathGunReadView, GunOwner>(),
  counters = new WeakMap<World, number>();

export function allDeathGuns(role: RoleComponent | undefined): DeathGunReadView[] {
  return Object.values(
    ((role as { readonly privateState: { readonly deathAbilities?: unknown } } | undefined)
      ?.privateState.deathAbilities ?? {}) as Readonly<Record<string, DeathGunReadView>>,
  ).sort((a, b) => a.id.localeCompare(b.id));
}

export function findDeathGun(
  role: RoleComponent | undefined,
  id: string,
): DeathGunReadView | undefined {
  return allDeathGuns(role).find((gun) => gun.id === id);
}

function bind(world: World, actorId: number, gun: DeathGun): void {
  const role = world.getComponent(actorId, COMPONENT.Role),
    life = world.getComponent(actorId, COMPONENT.Alive),
    version = life && aliveLifeVersion(life);
  if (!role || role.camp !== Camp.Good || !life?.alive || version === undefined)
    throw new Error("death_ability_owner_invalid");
  owners.set(gun, {
    world,
    actorId,
    role,
    roleKind: role.role,
    camp: role.camp,
    privateState: role.privateState,
    life,
    version,
    id: gun.id,
    source: gun.source,
    sourceKind: gun.source.kind,
    sourceActor: gun.source.actorId,
    ...(gun.source.kind === "transfer" ? { sourceId: gun.source.abilityId } : {}),
    grantedNight: gun.grantedNight,
    armedOnNight: gun.armedOnNight,
  });
}

export function deathGunOwnerCurrent(
  world: World,
  actorId: number,
  gun: DeathGunReadView,
  onDeath = false,
): boolean {
  const owner = owners.get(gun);
  if (!owner || owner.world !== world || owner.actorId !== actorId) return false;
  const version = aliveLifeVersion(owner.life);
  return (
    gun.id === owner.id &&
    gun.kind === "gun" &&
    gun.source === owner.source &&
    gun.source.kind === owner.sourceKind &&
    gun.source.actorId === owner.sourceActor &&
    (gun.source.kind === "gift" || gun.source.abilityId === owner.sourceId) &&
    gun.sourceDisclosed === false &&
    gun.grantedNight === owner.grantedNight &&
    gun.armedOnNight === owner.armedOnNight &&
    world.getComponent(actorId, COMPONENT.Role) === owner.role &&
    owner.role.role === owner.roleKind &&
    owner.role.camp === owner.camp &&
    owner.role.privateState === owner.privateState &&
    findDeathGun(owner.role, gun.id) === gun &&
    world.getComponent(actorId, COMPONENT.Alive) === owner.life &&
    (onDeath
      ? !owner.life.alive && version === owner.version + 1
      : owner.life.alive && version === owner.version)
  );
}

function emit(
  events: GameEvent[],
  actorId: number,
  gun: Pick<
    DeathGunReadView,
    "id" | "grantedNight" | "armedOnNight" | "remaining" | "disabled" | "deathExpired"
  >,
  operation: "granted" | "armed" | "disabled" | "enabled" | "transferred_out",
  abilityId = gun.id,
): void {
  events.push({
    timestamp: Date.now(),
    type: "death_ability_changed",
    payload: {
      actorId,
      abilityId,
      operation,
      grantedNight: gun.grantedNight,
      armedOnNight: gun.armedOnNight,
      remaining: gun.remaining,
      disabled: gun.disabled,
      deathExpired: gun.deathExpired,
    },
  });
}

/** 安装原体证明后写入目标库存，再推进计数并发表授予事实；发布失败保留此前写入，不回滚安装。 */
export function grantDeathGun(
  world: World,
  fromId: EntityId,
  toId: EntityId,
  night: number,
  events: GameEvent[],
): DeathGunReadView {
  const from = world.getComponent(fromId, COMPONENT.Role),
    to = world.getComponent(toId, COMPONENT.Role);
  if (
    fromId === toId ||
    !from ||
    from.camp !== Camp.Good ||
    !world.getComponent(fromId, COMPONENT.Alive)?.alive ||
    !to ||
    to.camp !== Camp.Good ||
    !world.getComponent(toId, COMPONENT.Alive)?.alive ||
    !Number.isSafeInteger(night) ||
    night < 1
  )
    throw new Error("death_ability_grant_invalid");
  if (allDeathGuns(to).length) throw new Error("death_ability_gun_already_owned");
  const next = (counters.get(world) ?? 0) + 1,
    id = `gift-gun:${next}`;
  if (
    (
      (to.privateState as { readonly retiredDeathAbilityIds?: unknown }).retiredDeathAbilityIds as
        string[] | undefined
    )?.includes(id)
  )
    throw new Error("death_ability_id_retired");
  const gun: DeathGun = {
    id,
    kind: "gun",
    source: { kind: "gift", actorId: fromId },
    sourceDisclosed: false,
    grantedNight: night,
    armedOnNight: null,
    remaining: 1,
    disabled: false,
    deathExpired: false,
  };
  bind(world, toId, gun);
  const stored = ((
    to.privateState as { deathAbilities?: Record<string, DeathGun> }
  ).deathAbilities ??= {}) as Record<string, DeathGun>;
  stored[id] = gun;
  counters.set(world, next);
  emit(events, toId, gun, "granted");
  return gun;
}

// 武装先核原 owner 与库存，随后依次写枪的 armedOnNight、证明中的同值，最后发布事实。
export function armDeathGun(
  world: World,
  actorId: number,
  gun: DeathGunReadView,
  night: number,
  events: GameEvent[],
): void {
  if (!Number.isSafeInteger(night) || night < gun.grantedNight)
    throw new Error("death_ability_activation_invalid");
  if (
    !deathGunOwnerCurrent(world, actorId, gun) ||
    gun.armedOnNight !== null ||
    gun.disabled ||
    gun.deathExpired ||
    gun.remaining === 0
  )
    return;
  (gun as { armedOnNight: number | null }).armedOnNight = night;
  owners.get(gun)!.armedOnNight = night;
  emit(events, actorId, gun, "armed");
}

export function activeDeathGun(
  world: World,
  actorId: number,
  id: string,
  day: number,
  onDeath = false,
): DeathGunReadView | undefined {
  const gun = findDeathGun(world.getComponent(actorId, COMPONENT.Role), id);
  return gun &&
    deathGunOwnerCurrent(world, actorId, gun, onDeath) &&
    gun.armedOnNight !== null &&
    gun.armedOnNight <= day &&
    gun.remaining === 1 &&
    !gun.disabled &&
    !gun.deathExpired
    ? gun
    : undefined;
}

/** 捕获的是原枪／来源字段并延迟核资格，不创建行动许可；剩弹、武装与当前性仍在实际查询时复核。 */
export function captureDeathGun(
  world: World,
  actorId: number,
  gun: DeathGunReadView,
  day: number,
  current: () => boolean,
) {
  const id = gun.id,
    kind = gun.kind,
    source = gun.source,
    sourceKind = source.kind,
    sourceActor = source.actorId,
    sourceId = source.kind === "transfer" ? source.abilityId : undefined;
  const disclosed = gun.sourceDisclosed,
    granted = gun.grantedNight,
    armed = gun.armedOnNight;
  const disabled = gun.disabled,
    expired = gun.deathExpired;
  const isCurrent = () =>
    current() &&
    gun.id === id &&
    gun.kind === kind &&
    gun.source === source &&
    gun.source.kind === sourceKind &&
    gun.source.actorId === sourceActor &&
    (gun.source.kind === "gift" || gun.source.abilityId === sourceId) &&
    gun.sourceDisclosed === disclosed &&
    gun.grantedNight === granted &&
    gun.armedOnNight === armed &&
    gun.disabled === disabled &&
    gun.deathExpired === expired &&
    deathGunOwnerCurrent(world, actorId, gun, true);
  return {
    isCurrent,
    isEligible: () => isCurrent() && activeDeathGun(world, actorId, id, day, true) === gun,
  };
}

// 死亡回调前捕获原枪及发布字段；首次死亡的 version+1 保持枪权，不能提前永久到期。
export function firstDeathGuns(
  world: World,
  actorId: number,
): Array<{
  actorId: number;
  gun: DeathGunReadView;
  id: string;
  grantedNight: number;
  armedOnNight: number | null;
}> {
  return allDeathGuns(world.getComponent(actorId, COMPONENT.Role))
    .filter((gun) => !gun.deathExpired && deathGunOwnerCurrent(world, actorId, gun, true))
    .map((gun) => ({
      actorId,
      gun,
      id: gun.id,
      grantedNight: gun.grantedNight,
      armedOnNight: gun.armedOnNight,
    }));
}

// 外层收尾逐枪依次清剩弹、禁用、标永久到期；事实只用先前捕获字段，失败不回滚已写前缀。
export function finishDeathGuns(
  rows: ReturnType<typeof firstDeathGuns>,
  events: GameEvent[],
): void {
  for (const { actorId, gun, id, grantedNight, armedOnNight } of rows) {
    if (gun.deathExpired) continue;
    (gun as { remaining: 0 | 1 }).remaining = 0;
    (gun as { disabled: boolean }).disabled = true;
    (gun as { deathExpired: boolean }).deathExpired = true;
    emit(
      events,
      actorId,
      { id, grantedNight, armedOnNight, remaining: 0, disabled: true, deathExpired: true },
      "disabled",
      id,
    );
  }
}

export function setDeathGunEnabled(
  world: World,
  actorId: number,
  id: string,
  enabled: boolean,
  events: GameEvent[],
): void {
  const gun = findDeathGun(world.getComponent(actorId, COMPONENT.Role), id);
  if (!gun || !deathGunOwnerCurrent(world, actorId, gun))
    throw new Error("death_ability_instance_unavailable");
  if (enabled && gun.deathExpired) throw new Error("death_ability_expired");
  if (gun.disabled === !enabled) return;
  (gun as { disabled: boolean }).disabled = !enabled;
  emit(events, actorId, gun, enabled ? "enabled" : "disabled");
}

// 先建立接收者新证明／库存，再删源实例、登记退休 ID，最后源转出→目标授予；不直接搬旧对象。
export function transferDeathGun(
  world: World,
  fromId: number,
  toId: number,
  id: string,
  events: GameEvent[],
): DeathGunReadView {
  const source = world.getComponent(fromId, COMPONENT.Role),
    target = world.getComponent(toId, COMPONENT.Role),
    gun = findDeathGun(source, id);
  if (
    !gun ||
    fromId === toId ||
    !deathGunOwnerCurrent(world, fromId, gun) ||
    !target ||
    target.camp !== Camp.Good ||
    !world.getComponent(toId, COMPONENT.Alive)?.alive ||
    allDeathGuns(target).length ||
    (
      (target.privateState as { readonly retiredDeathAbilityIds?: unknown })
        .retiredDeathAbilityIds as string[] | undefined
    )?.includes(id)
  )
    throw new Error("death_ability_transfer_invalid");
  const received: DeathGun = {
    ...projectDeathGun(gun),
    source: { kind: "transfer", actorId: fromId, abilityId: id },
  };
  delete (received as DeathGun & { status?: string }).status;
  bind(world, toId, received);
  (
    ((target.privateState as { deathAbilities?: Record<string, DeathGun> }).deathAbilities ??=
      {}) as Record<string, DeathGun>
  )[id] = received;
  delete (
    (source!.privateState as { readonly deathAbilities?: unknown }).deathAbilities as Record<
      string,
      DeathGun
    >
  )[id];
  (
    ((source!.privateState as { retiredDeathAbilityIds?: string[] }).retiredDeathAbilityIds ??=
      []) as string[]
  ).push(id);
  emit(events, fromId, gun, "transferred_out");
  emit(events, toId, received, "granted");
  return received;
}

// 枪目标、生命与行动许可由调用者复核；这里只将原枪剩弹写为 0，不新增授权、复检或事实。
export function consumeDeathGunShot(gun: DeathGunReadView): void {
  (gun as { remaining: 0 | 1 }).remaining = 0;
}

